document.querySelectorAll('body > pre').forEach(pre => {
    const t = pre.textContent.trim();
    if (t.startsWith('end of thread') || t.startsWith('This is a public inbox')) {
        pre.setAttribute('data-kiss-skip', '');
    }
});
